import{_ as e,o as t,c as r,a2 as l}from"./chunks/framework.DDY-poMm.js";const _=JSON.parse('{"title":"安全设计","description":"","frontmatter":{},"headers":[],"relativePath":"zh/wallet/security.md","filePath":"zh/wallet/security.md","lastUpdated":1793861180000}'),i={name:"zh/wallet/security.md"};function o(s,a,n,c,d,h){return t(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="安全设计" tabindex="-1">安全设计 <a class="header-anchor" href="#安全设计" aria-label="Permalink to &quot;安全设计&quot;">​</a></h1><h2 id="自托管-平台不碰私钥" tabindex="-1">自托管，平台不碰私钥 <a class="header-anchor" href="#自托管-平台不碰私钥" aria-label="Permalink to &quot;自托管，平台不碰私钥&quot;">​</a></h2><p>助记词只保存在用户手机里，用设备的安全芯片加密，服务器上没有任何私钥。支持 Face ID；密码连续输错会逐级延长锁定时间。一个 App 可管理多个钱包，也可导入已有私钥。</p><h2 id="防篡改" tabindex="-1">防篡改 <a class="header-anchor" href="#防篡改" aria-label="Permalink to &quot;防篡改&quot;">​</a></h2><p>按「即使代码被看穿也偷不到钱」设计：安装包代码混淆；可识别 root / 越狱、调试器与挂钩工具，在被攻击的环境中拒绝查看助记词和签名交易。交易白名单由平台离线签名、App 内置公钥验证，即使服务器被入侵也无法替换交易对象。安卓支持硬件密钥证明，用于识别被改包的非官方 App；安卓版有新版本时可在 App 内下载，校验安装包完整性后再安装。</p><h2 id="安全须知" tabindex="-1">安全须知 <a class="header-anchor" href="#安全须知" aria-label="Permalink to &quot;安全须知&quot;">​</a></h2><ul><li>平台不保存私钥，<strong>助记词一旦丢失无法找回</strong>，请务必离线备份。</li><li>代币化股票由发行方发行。持有人不享有股东投票权，发行方可在特定情况下暂停转账。</li><li>链上交易一经确认不可撤销。</li><li>预测交易可能亏损；跨链充值和提现由 Polymarket 官方跨链服务完成，链上转账一经确认不可撤销。</li></ul>',7)])])}const u=e(i,[["render",o]]);export{_ as __pageData,u as default};
